using FluentValidation;
namespace OAS.Application.Accounting.ReceiptVouchers.Commands.CreateReceiptVoucher;
public sealed class CreateReceiptVoucherCommandValidator:AbstractValidator<CreateReceiptVoucherCommand>{public CreateReceiptVoucherCommandValidator(){RuleFor(x=>x.Data.Lines).NotEmpty().WithErrorCode("receipt_voucher_lines_required");RuleFor(x=>x.Data.Description).MaximumLength(500);RuleForEach(x=>x.Data.Lines).ChildRules(l=>{l.RuleFor(x=>x.CurrencyId).NotEmpty();l.RuleFor(x=>x.Amount).GreaterThan(0);l.RuleFor(x=>x.ExchangeRate).GreaterThan(0).When(x=>x.ExchangeRate.HasValue);l.RuleFor(x=>x.PartyName).MaximumLength(200);l.RuleFor(x=>x.ReferenceNumber).MaximumLength(100);l.RuleFor(x=>x.ReferenceType).MaximumLength(50);l.RuleFor(x=>x.Description).MaximumLength(300);});}}
